// Reading and writing a project's architecture folder:
//
//   architecture/
//     archmap.config.json   name, logo, theme, labels (the white-label settings)
//     instructions.md       how to record a change; the viewer and the Claude skill show it
//     versions.json         { "versions": [{ id, name, published_at, summary, saves }] }
//     saves/<id>.json       one save each: { at, author, summary, ops }
//     current.json          generated by `archmap snapshot`: the latest state, for reading

import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import { join } from "node:path";
import {
  buildVersions,
  checkModel,
  replay,
  validateSave,
  type Save,
  type Version,
} from "./core.ts";
import type { WatchEntry } from "./watch.ts";

export type Config = {
  name: string;
  product?: string;
  logo?: string;
  theme?: { light?: Record<string, string>; dark?: Record<string, string> };
  fonts?: { stylesheet?: string; sans?: string; mono?: string };
  labels?: {
    boundary?: string;
    boundarySub?: string;
    outside?: string;
    outsideSub?: string;
  };
  links?: { label: string; url: string }[];
  watch?: WatchEntry[];
};

export type Project = {
  dir: string;
  config: Config;
  saves: Save[];
  versions: Version[];
  instructions: string;
  /** Files that couldn't be read or don't have the right shape. */
  fileErrors: string[];
};

export const DEFAULT_DIR = "architecture";

const readJson = (path: string): unknown =>
  JSON.parse(readFileSync(path, "utf8"));

export const writeJson = (path: string, data: unknown): void => {
  writeFileSync(path, JSON.stringify(data, null, 2) + "\n");
};

export const loadProject = (dir: string): Project => {
  if (!existsSync(join(dir, "archmap.config.json"))) {
    throw new Error(
      `No architecture map in ${dir}. Run \`archmap init\` first, or pass --dir.`,
    );
  }
  const fileErrors: string[] = [];
  let config: Config = { name: "Architecture" };
  try {
    config = readJson(join(dir, "archmap.config.json")) as Config;
    if (typeof config.name !== "string" || !config.name)
      fileErrors.push(`archmap.config.json: "name" is required`);
  } catch (err) {
    fileErrors.push(`archmap.config.json: ${(err as Error).message}`);
  }
  const saves: Save[] = [];
  const savesDir = join(dir, "saves");
  if (existsSync(savesDir)) {
    readdirSync(savesDir)
      .filter((f) => f.endsWith(".json"))
      .sort()
      .forEach((file) => {
        const id = file.slice(0, -5);
        try {
          const raw = readJson(join(savesDir, file));
          const errors = validateSave(raw, id);
          if (errors.length) fileErrors.push(...errors);
          else saves.push({ ...(raw as Omit<Save, "id">), id });
        } catch (err) {
          fileErrors.push(`${id}: ${(err as Error).message}`);
        }
      });
  }
  let versions: Version[] = [];
  const vpath = join(dir, "versions.json");
  if (existsSync(vpath)) {
    try {
      const raw = readJson(vpath) as { versions?: Version[] };
      versions = Array.isArray(raw.versions) ? raw.versions : [];
      const ids = new Set(saves.map((s) => s.id));
      versions.forEach((v) =>
        v.saves.forEach((sid) => {
          if (!ids.has(sid))
            fileErrors.push(
              `versions.json: ${v.name} lists save ${sid}, which doesn't exist`,
            );
        }),
      );
    } catch (err) {
      fileErrors.push(`versions.json: ${(err as Error).message}`);
    }
  }
  const ipath = join(dir, "instructions.md");
  const instructions = existsSync(ipath) ? readFileSync(ipath, "utf8") : "";
  return { dir, config, saves, versions, instructions, fileErrors };
};

/** Every problem in the project: bad files, then changes that don't apply or leave broken links, per version. */
export const projectProblems = (p: Project): string[] => {
  const out = [...p.fileErrors];
  const seen = new Set(out);
  buildVersions(p.saves, p.versions).forEach((v) => {
    const m = replay(p.saves, v.set);
    // A problem carried from one version into the next is reported once, at its first version.
    [...m.problems, ...checkModel(m)].forEach((msg) => {
      if (seen.has(msg)) return;
      seen.add(msg);
      out.push(`${v.name}: ${msg}`);
    });
  });
  return out;
};

export const ensureDir = (path: string): void => {
  mkdirSync(path, { recursive: true });
};

export const slugify = (text: string): string =>
  text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 40) || "save";

/** A sortable save id: UTC timestamp then a short slug, e.g. 20261120-180400-add-hour-type. */
export const saveId = (summary: string, now = new Date()): string => {
  const iso = now.toISOString();
  return (
    iso.slice(0, 10).replace(/-/g, "") +
    "-" +
    iso.slice(11, 19).replace(/:/g, "") +
    "-" +
    slugify(summary)
  );
};
